function bfs(adj, start) {
  const visited = new Array(adj.length).fill(false);
  const order = [];
  const queue = [start];
  visited[start] = true;               // mark on the way IN, so nobody adds it twice
  let head = 0;                        // the queue's front (faster than queue.shift())
  while (head < queue.length) {
    const u = queue[head++];           // the oldest vertex: the nearest one left
    order.push(u);
    for (const v of adj[u]) {
      if (!visited[v]) {
        visited[v] = true;
        queue.push(v);                 // one ring further out
      }
    }
  }
  return order;
}

List<Integer> bfs(List<List<Integer>> adj, int start) {
    boolean[] visited = new boolean[adj.size()];
    List<Integer> order = new ArrayList<>();
    ArrayDeque<Integer> queue = new ArrayDeque<>();
    queue.add(start);
    visited[start] = true;             // mark on the way IN, so nobody adds it twice
    while (!queue.isEmpty()) {
        int u = queue.poll();          // the oldest vertex: the nearest one left
        order.add(u);
        for (int v : adj.get(u)) {
            if (!visited[v]) {
                visited[v] = true;
                queue.add(v);          // one ring further out
            }
        }
    }
    return order;
}

vector<int> bfs(vector<vector<int>>& adj, int start) {
    vector<bool> visited(adj.size(), false);
    vector<int> order;
    queue<int> q;
    q.push(start);
    visited[start] = true;             // mark on the way IN, so nobody adds it twice
    while (!q.empty()) {
        int u = q.front(); q.pop();    // the oldest vertex: the nearest one left
        order.push_back(u);
        for (int v : adj[u]) {
            if (!visited[v]) {
                visited[v] = true;
                q.push(v);             // one ring further out
            }
        }
    }
    return order;
}

function dfs(adj, start) {
  const visited = new Array(adj.length).fill(false);
  const order = [];
  const visit = (u) => {
    visited[u] = true;
    order.push(u);
    for (const v of adj[u]) {
      if (!visited[v]) visit(v);       // go deep before trying the next neighbour
    }
  };
  visit(start);
  return order;
}

