void visit(List<List<Integer>> adj, int u, boolean[] visited, List<Integer> order) {
    visited[u] = true;
    order.add(u);
    for (int v : adj.get(u)) {
        if (!visited[v]) visit(adj, v, visited, order);   // go deep before the next neighbour
    }
}

void visit(vector<vector<int>>& adj, int u, vector<bool>& visited, vector<int>& order) {
    visited[u] = true;
    order.push_back(u);
    for (int v : adj[u]) {
        if (!visited[v]) visit(adj, v, visited, order);   // go deep before the next neighbour
    }
}

